210: function readDnaBank() {
211:   try {
212:     const parsed = JSON.parse(localStorage.getItem(DNA_BANK_KEY) || "[]");
213:     if (!Array.isArray(parsed)) return [];
214:     return parsed.filter((entry) => entry && typeof entry.id === "string" &&
215:       typeof entry.name === "string" && entry.genome &&
216:       GENE_KEYS.every((key) => Number.isFinite(entry.genome[key]) && entry.genome[key] >= 0 && entry.genome[key] <= 1));
217:   } catch {
218:     return [];
219:   }
220: }
