222: function writeDnaBank(entries) {
223:   try {
224:     localStorage.setItem(DNA_BANK_KEY, JSON.stringify(entries.slice(0, DNA_BANK_LIMIT)));
225:     return true;
226:   } catch {
227:     showToast("Archive unavailable", "Browser storage is full or disabled", "!", 3200);
228:     return false;
229:   }
230: }
