232: function renderDnaBank() {
233:   const entries = readDnaBank();
234:   els.dnaCount.textContent = `${entries.length} archived genome${entries.length === 1 ? "" : "s"}`;
235:   els.dnaList.replaceChildren();
236:   if (!entries.length) {
237:     const empty = document.createElement("p");
238:     empty.className = "dna-empty";
239:     empty.textContent = "No genomes archived yet. Save the selected specimen to begin a lineage library.";
240:     els.dnaList.append(empty);
241:     return;
242:   }
243: 
244:   for (const entry of entries) {
245:     const card = document.createElement("article");
246:     card.className = "dna-entry";
247:     const details = document.createElement("div");
248:     details.className = "dna-entry-copy";
249:     const name = document.createElement("strong");
250:     name.textContent = entry.name;
251:     const meta = document.createElement("span");
252:     const date = new Date(entry.savedAt);
253:     meta.textContent = `${entry.latin || "Archived genome"} · G${pad(entry.generation || 1)} · ${Number.isNaN(date.getTime()) ? "saved previously" : date.toLocaleDateString()}`;
254:     details.append(name, meta);
255: 
256:     const actions = document.createElement("div");
257:     actions.className = "dna-entry-actions";
258:     const restore = document.createElement("button");
259:     restore.className = "button button-quiet";
260:     restore.type = "button";
261:     restore.dataset.restoreGenome = entry.id;
262:     restore.textContent = "Restore";
263:     const remove = document.createElement("button");
264:     remove.className = "dna-remove";
265:     remove.type = "button";
266:     remove.dataset.removeGenome = entry.id;
267:     remove.setAttribute("aria-label", `Remove ${entry.name} from DNA bank`);
268:     remove.textContent = "×";
269:     actions.append(restore, remove);
270:     card.append(details, actions);
271:     els.dnaList.append(card);
272:   }
273: }
