295: function restoreGenome(id) {
296:   const entry = readDnaBank().find((item) => item.id === id);
297:   const org = currentOrganism();
298:   if (!entry || !org) return;
299:   org.genome = Object.fromEntries(GENE_KEYS.map((key) => [key, entry.genome[key]]));
300:   org.evaluation = evaluate(org.genome, state.env, org.condition);
301:   org.origin = "DNA bank";
302:   org.changes = [];
303:   org.parents = [];
304:   creatures.replace(creatures.selectedIndex, org);
305:   updateAll();
306:   addLog(`Archived genome <b>${entry.name}</b> restored to specimen K-${pad(creatures.selectedIndex + 1)}.`, true);
307:   showToast("Genome restored", `${entry.name} now occupies the selected specimen`, "◈", 3000);
308:   audio.select();
309: }
