389: function updateDNAAnalyser(genome) {
390:   const analysis = analyzeGenome(genome);
391:   els.dnaPairCount.textContent = `${analysis.basePairs} bp`;
392:   els.dnaGcContent.textContent = `${analysis.gcContent.toFixed(1)}%`;
393:   els.dnaSequence.innerHTML = analysis.genes.map((gene) => `
394:     <div class="dna-gene" title="${gene.label}: ${gene.value.toFixed(3)}">
395:       <span class="dna-gene-code">${gene.code}</span>
396:       <span class="dna-gene-bases">${[...gene.sequence].map((base) => `<i class="base-${base}">${base}</i>`).join("")}</span>
397:     </div>`).join("");
398: 
399:   const labels = {
400:     muscle: "Muscle", bones: "Bones", neurons: "Neurons",
401:     fat: "Adipose", nerves: "Nerves", ears: "Ears",
402:   };
403:   els.dnaSystems.innerHTML = Object.entries(analysis.systems).map(([system, value]) => `
404:     <div class="dna-system" title="${labels[system]} expression ${Math.round(value * 100)}%">
405:       <span>${labels[system]}</span>
406:       <div class="dna-system-track"><i style="width:${Math.round(value * 100)}%"></i></div>
407:       <b>${Math.round(value * 100)}</b>
408:     </div>`).join("");
409: }
