411: function updateSelectionUI() {
412:   const org = currentOrganism();
413:   const creature = creatures.selected;
414:   if (!org || !creature) return;
415:   updateDNAAnalyser(org.genome);
416: 
417:   const name = nameCreature(org.genome);
418:   const color = creatureColorHex(creature);
419:   els.panel.style.setProperty("--specimen-color", color);
420:   els.specimenGlyph.style.setProperty("--specimen-color", color);
421:   const hslColor = new THREE.Color(color);
422:   const hsl = {};
423:   hslColor.getHSL(hsl);
424:   els.specimenLatin.style.color = `hsl(${Math.round(hsl.h * 360)}, 28%, 58%)`;
425: 
426:   const cellular = state.stage === "cellular";
427:   els.specimenId.textContent = `${cellular ? "CELL" : "SPECIMEN"} K-${pad(creatures.selectedIndex + 1)}`;
428:   els.specimenName.textContent = name.common;
429:   els.specimenLatin.textContent = cellular ? `cellular lineage · ${name.latin}` : name.latin;
430:   els.dossierHeading.textContent = cellular ? "Cell dossier" : "Specimen dossier";
431:   els.traitHeading.textContent = cellular ? "Cellular gene expression" : "Trait expression";
432:   els.stageNote.textContent = cellular
433:     ? "Cellular stage · membrane-bound cell with nucleus, nucleolus, mitochondria & ribosomes"
434:     : "Organism stage · multicellular form with differentiated body systems";
435:   els.diet.textContent = cellular ? "Eukaryote" : org.genome.armor > 0.66 ? "Omnivore" : org.genome.neck > 0.62 ? "Browser" : "Grazer";
436:   els.plan.textContent = cellular ? "Single cell" : org.genome.legs > 0.66 ? "Cursorial" : "Quadruped";
437:   els.creatureTagName.textContent = name.common;
438:   els.creatureTagMeta.textContent = `${cellular ? "cell" : "specimen"} K-${pad(creatures.selectedIndex + 1)} · fitness ${Math.round(org.evaluation.fitness)}`;
439: 
440:   const fitness = org.evaluation.fitness;
441:   const ringColor = fitnessColor(fitness);
442:   const deg = fitness * 3.6;
443:   els.fitnessRing.style.background = `conic-gradient(${ringColor} 0deg ${deg}deg, rgba(255,255,255,0.07) ${deg}deg 360deg)`;
444:   els.fitnessRing.style.setProperty("--ring-color", ringColor);
445:   els.specimenFitness.textContent = Math.round(fitness);
446:   els.specimenFitness.style.color = ringColor;
447:   els.fitThermal.textContent = Math.round(org.evaluation.components.thermal);
448:   els.fitForage.textContent = Math.round(org.evaluation.components.foraging);
449:   els.fitDefense.textContent = Math.round(org.evaluation.components.defense);
450:   els.fitEnergy.textContent = Math.round(org.evaluation.components.efficiency);
451: 
452:   const status = fitness >= 72 ? "Thriving" : fitness >= 56 ? "Stable" : "Stressed";
453:   els.status.textContent = status;
454:   els.status.style.color = fitness >= 56 ? "var(--mint)" : "var(--coral)";
455:   const weightValues = org.evaluation.weights;
456:   const weightTotal = Object.values(weightValues).reduce((sum, value) => sum + value, 0);
457:   for (const key of ["thermal", "foraging", "defense", "efficiency"]) {
458:     const percentage = (weightValues[key] / weightTotal) * 100;
459:     els.weights[key][0].style.width = `${percentage}%`;
460:     els.weights[key][1].textContent = `${Math.round(percentage)}%`;
461:   }
462: 
463:   const targets = traitTargets(state.env);
464:   const rows = [...els.traitList.querySelectorAll(".trait")];
465:   for (const row of rows) {
466:     const key = row.dataset.gene;
467:     const raw = org.genome[key];
468:     row.querySelector("[data-value]").textContent = traitDisplay(key, raw);
469:     row.querySelector("[data-fill]").style.width = `${clamp(raw, 0, 1) * 100}%`;
470:     const optimum = row.querySelector("[data-optimum]");
471:     optimum.style.left = `${clamp(targets[key] ?? 0.5, 0.02, 0.98) * 100}%`;
472:   }
473: 
474:   els.mutagenPips.innerHTML = Array.from({ length: 5 }, (_, i) => `<i class="${i < state.mutagen ? "full" : ""}"></i>`).join("");
475:   els.btnMutate.disabled = state.mutagen <= 0;
476:   renderPopDots();
477: }
