510: function drawChart() {
511:   const canvas = els.chart;
512:   const ctx = canvas.getContext("2d");
513:   const width = canvas.width;
514:   const height = canvas.height;
515:   ctx.clearRect(0, 0, width, height);
516: 
517:   const values = state.history.slice(-20);
518:   const min = 28;
519:   const max = 96;
520:   const padX = 5;
521:   const padY = 13;
522: 
523:   ctx.save();
524:   ctx.strokeStyle = "rgba(180, 255, 220, 0.08)";
525:   ctx.lineWidth = 1;
526:   ctx.setLineDash([3, 7]);
527:   for (let i = 0; i < 4; i += 1) {
528:     const y = padY + ((height - padY * 2) / 3) * i;
529:     ctx.beginPath();
530:     ctx.moveTo(0, y);
531:     ctx.lineTo(width, y);
532:     ctx.stroke();
533:   }
534:   ctx.restore();
535: 
536:   if (!values.length) return;
