17: export function terrainHeight(x, z) {
18:   const r = Math.hypot(x, z);
19:   let h = Math.sin(x * 0.52) * 0.034 + Math.cos(z * 0.67) * 0.03 + Math.sin((x + z) * 1.17) * 0.013;
20:   h *= smooth(0.8, 4.4, r);
21:   h += smooth(8.2, 10.4, r) * 0.18;
22:   const pondD = Math.hypot(x - POND.x, z - POND.z);
23:   h -= (1 - smooth(POND.radius * 0.3, POND.radius * 1.12, pondD)) * 0.14;
24:   return h;
25: }
