575:   buildBodySystems({ bodyLen, bodyW, bodyH, bodyY, neckLen, legLen }) {
576:     const { muscle, bones, neurons, fat, nerves } = this.systems;
577:     const addTube = (coordinates, radius, material, segments = 20) => {
578:       const curve = new THREE.CatmullRomCurve3(coordinates.map(([x, y, z]) => new THREE.Vector3(x, y, z)));
579:       const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, segments, radius, 5, false), material);
580:       tube.castShadow = false;
581:       this.model.add(tube);
582:       return curve;
583:     };
584: 
585:     // Pale vertebrae and paired leg struts make skeletal expression legible in the living body.
586:     const vertebraCount = 4 + Math.round(bones * 3);
587:     for (let i = 0; i < vertebraCount; i += 1) {
588:       const t = i / Math.max(1, vertebraCount - 1);
589:       const vertebra = new THREE.Mesh(this.torsoGeo, this.boneMat);
590:       const scale = 0.018 + bones * 0.018;
591:       vertebra.scale.set(scale, scale * 0.72, scale * 1.16);
592:       vertebra.position.set(0, bodyY + bodyH * 0.83, (t - 0.5) * bodyLen * 1.08);
593:       this.model.add(vertebra);
594:     }
595: 
596:     // Adipose lobes follow the FTO/body-mass expression rather than being decorative static spots.
597:     const lobeScale = 0.018 + fat * 0.038;
598:     for (const side of [-1, 1]) {
599:       for (const z of [-0.42, 0, 0.42]) {
600:         const lobe = new THREE.Mesh(this.torsoGeo, this.bellyMat);
601:         lobe.scale.set(lobeScale, lobeScale * 0.72, lobeScale * 1.18);
602:         lobe.position.set(side * bodyW * 0.76, bodyY - bodyH * 0.55, z * bodyLen);
603:         this.model.add(lobe);
604:       }
605:     }
606: 
607:     // A luminous central nerve cord links the head to peripheral branches and sensory nodes.
608:     const spinePath = [
609:       [0, bodyY + bodyH * 0.75, -bodyLen * 0.58],
610:       [0, bodyY + bodyH * 0.83, -bodyLen * 0.2],
611:       [0, bodyY + bodyH * 0.86, bodyLen * 0.24],
612:       [0, bodyY + bodyH * 0.75, bodyLen * 0.62],
613:       [0, bodyY + bodyH * 0.86 + neckLen * 0.32, bodyLen * 0.78 + neckLen * 0.28],
614:       [0, bodyY + bodyH * 0.86 + neckLen * 0.72, bodyLen * 0.78 + neckLen * 0.58],
615:     ];
616:     const spineCurve = addTube(spinePath, 0.006 + nerves * 0.006, this.neuralMat, 30);
617:     const nodeCount = 4 + Math.round(neurons * 5);
618:     for (let i = 0; i < nodeCount; i += 1) {
619:       const point = spineCurve.getPoint(i / Math.max(1, nodeCount - 1));
620:       const node = new THREE.Mesh(this.torsoGeo, this.neuralMat);
621:       node.scale.setScalar(0.018 + neurons * 0.018);
622:       node.position.copy(point);
623:       this.model.add(node);
624:     }
