626:     const branchRadius = 0.0035 + nerves * 0.004;
627:     for (const side of [-1, 1]) {
628:       for (const z of [-bodyLen * 0.5, bodyLen * 0.48]) {
629:         addTube([
630:           [0, bodyY + bodyH * 0.8, z * 0.66],
631:           [side * bodyW * 0.35, bodyY + bodyH * 0.64, z * 0.82],
632:           [side * bodyW * 0.8, bodyY - bodyH * 0.1, z],
633:           [side * bodyW * 0.82, Math.max(0.12, bodyY - legLen * 0.66), z],
634:         ], branchRadius, this.neuralMat, 12);
635:       }
636:     }
637: 
638:     // Muscle mass also subtly thickens the upper limbs; this warm inset marks the contractile tissue.
639:     this.muscleMat.emissiveIntensity = 0.04 + muscle * 0.09;
640:   }
