723:   chooseTarget(initial = false) {
724:     const angle = this.rng() * TAU;
725:     const dist = initial ? 0 : (this.index === 0 ? 0.8 : 1.1) + this.rng() * (this.index === 0 ? 1.7 : 2.2);
726:     let x = this.home.x + Math.cos(angle) * dist;
727:     let z = this.home.z + Math.sin(angle) * dist;
728: 
729:     if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.8) {
730:       x = this.home.x - Math.cos(angle) * dist;
731:       z = this.home.z - Math.sin(angle) * dist;
732:     }
733:     const r = Math.hypot(x, z);
734:     if (r > 7.1) {
735:       x *= 7.1 / r;
736:       z *= 7.1 / r;
737:     }
738:     this.target.set(x, 0, z);
739:   }
740: 
741:   update(dt) {
742:     const elapsed = this.world.time - this.spawnTime;
743:     const spawnT = clamp01(elapsed / 0.8);
744:     this.model.scale.setScalar(this.sizeScale * Math.max(0.01, easeOutBack(spawnT)));
745:     this.model.visible = spawnT > 0;
746:     if (spawnT < 1) {
747:       this.model.rotation.z = Math.sin(spawnT * Math.PI) * 0.04;
748:       return;
749:     }
750:     this.model.rotation.z *= 0.9;
751: 
752:     if (this.stage === "cellular") {
753:       const time = this.world.time;
754:       this.model.position.y = Math.sin(time * 1.3 + this.index) * 0.035;
755:       this.cellGroup.rotation.y = time * 0.12 + this.index * 0.4;
756:       this.cellNucleus.scale.setScalar(1 + Math.sin(time * 1.7 + this.index) * 0.025);
757:       this.cellOrganelles.forEach((organelle, index) => {
758:         organelle.rotation.y += dt * (index % 2 ? -0.12 : 0.16);
759:       });
760:       this.position.y = terrainHeight(this.position.x, this.position.z);
761:       this.group.position.y = this.position.y;
762:       return;
763:     }
764: 
765:     const speedGene = 0.6 + this.genome.speed * 1.45;
766:     this.tempTarget.set(this.target.x - this.position.x, 0, this.target.z - this.position.z);
767:     const distance = this.tempTarget.length();
768:     if (distance < 0.22 || this.rng() < dt * 0.008) {
769:       this.chooseTarget();
770:     }
771: 
772:     const moving = distance > 0.35;
773:     this.moving = moving;
774:     if (moving) {
775:       this.tempTarget.normalize();
776:       const desired = Math.atan2(this.tempTarget.x, this.tempTarget.z);
777:       let diff = desired - this.heading;
778:       while (diff > Math.PI) diff -= TAU;
779:       while (diff < -Math.PI) diff += TAU;
780:       this.heading += diff * Math.min(1, dt * 2.4);
781:       this.group.rotation.y = this.heading;
782: 
783:       const step = Math.min(distance, dt * (0.16 + speedGene * 0.22));
784:       const nx = this.position.x + Math.sin(this.heading) * step;
785:       const nz = this.position.z + Math.cos(this.heading) * step;
786:       if (Math.hypot(nx - POND.x, nz - POND.z) > POND.radius + 0.5 && Math.hypot(nx, nz) < 7.35) {
787:         this.position.x = nx;
788:         this.position.z = nz;
789:       } else {
790:         this.chooseTarget();
791:       }
792:       this.walkPhase += dt * (3.9 + speedGene * 2.8);
793:     } else {
794:       this.walkPhase += dt * 1.1;
795:     }
796: 
797:     this.position.y = terrainHeight(this.position.x, this.position.z);
798:     this.group.position.x = this.position.x;
799:     this.group.position.z = this.position.z;
800:     this.group.position.y = this.position.y;
801: 
802:     const stride = moving ? 1 : 0.25;
803:     for (const leg of this.legs) {
804:       const swing = Math.sin(this.walkPhase + leg.phase) * 0.54 * stride;
805:       const lift = Math.max(0, Math.sin(this.walkPhase + leg.phase + Math.PI / 2)) * 0.28 * stride;
806:       leg.root.rotation.x = leg.baseRot + swing;
807:       leg.knee.rotation.x = -lift + (leg.front ? 0.18 : 0.32);
808:     }
809: 
810:     const bob = moving ? Math.abs(Math.sin(this.walkPhase)) * 0.026 : Math.sin(this.world.time * 1.4) * 0.006;
811:     this.model.position.y = bob;
812:     this.model.rotation.x = moving ? Math.sin(this.walkPhase) * 0.008 : 0;
813: 
814:     if (this.neckGroup) {
815:       this.neckGroup.rotation.z = Math.sin(this.walkPhase * 0.5 + 1.2) * 0.022;
816:       this.neckGroup.rotation.x = (0.62 + this.genome.neck * 0.2) + Math.sin(this.walkPhase * 0.5) * 0.027;
817:     }
