271: export function diversity(population) {
272:   if (population.length < 2) return 0;
273:   let sum = 0;
274:   let count = 0;
275:   for (let i = 0; i < population.length; i += 1) {
276:     for (let j = i + 1; j < population.length; j += 1) {
277:       let d = 0;
278:       for (const key of GENE_KEYS) {
279:         d += Math.abs(population[i].genome[key] - population[j].genome[key]);
280:       }
281:       sum += d / GENE_KEYS.length;
282:       count += 1;
283:     }
284:   }
