292: export function breedPopulation(population, env, rng = Math.random) {
293:   const ranked = rankPopulation(population);
294:   const eliteCount = Math.max(2, Math.round(population.length * 0.34));
295:   const parents = ranked.slice(0, Math.max(3, eliteCount));
296:   const next = [];
297: 
298:   // A true survivor keeps its exact alleles and becomes the first hatchling.
299:   next.push({ genome: { ...parents[0].genome }, origin: "elite", changes: [] });
300: 
301:   while (next.length < population.length) {
302:     const a = weightedParent(parents, rng);
303:     let b = weightedParent(parents, rng);
304:     if (parents.length > 1) {
305:       let guard = 0;
306:       while (b === a && guard < 8) {
307:         b = weightedParent(parents, rng);
308:         guard += 1;
309:       }
310:     }
311:     let genome = a === b ? { ...a.genome } : crossover(a.genome, b.genome, rng);
312:     const mutation = mutate(genome, rng, next.length === 1 ? 0.08 : 0.18, 0.1);
313:     genome = mutation.genome;
314:     next.push({
315:       genome,
316:       origin: next.length === 1 ? "elite-mutant" : "offspring",
317:       changes: mutation.changes,
318:       parents: [a.id, b.id],
319:     });
320:   }
321: 
322:   return next;
323: }
324: 
325: function weightedParent(parents, rng) {
326:   const weights = parents.map((p) => Math.pow(Math.max(1, p.evaluation.fitness), 2.4));
327:   const total = weights.reduce((a, b) => a + b, 0);
328:   let roll = rng() * total;
329:   for (let i = 0; i < parents.length; i += 1) {
330:     roll -= weights[i];
331:     if (roll <= 0) return parents[i];
332:   }
333:   return parents[parents.length - 1];
334: }
