510: function drawChart() {
511:   const canvas = els.chart;
512:   const ctx = canvas.getContext("2d");
513:   const width = canvas.width;
514:   const height = canvas.height;
515:   ctx.clearRect(0, 0, width, height);
516: 
517:   const values = state.history.slice(-20);
518:   const min = 28;
519:   const max = 96;
520:   const padX = 5;
521:   const padY = 13;
522: 
523:   ctx.save();
524:   ctx.strokeStyle = "rgba(180, 255, 220, 0.08)";
525:   ctx.lineWidth = 1;
526:   ctx.setLineDash([3, 7]);
527:   for (let i = 0; i < 4; i += 1) {
528:     const y = padY + ((height - padY * 2) / 3) * i;
529:     ctx.beginPath();
530:     ctx.moveTo(0, y);
531:     ctx.lineTo(width, y);
532:     ctx.stroke();
533:   }
534:   ctx.restore();
535: 
536:   if (!values.length) return;
537: 
538:   const graphValues = values.length === 1 ? [values[0], values[0]] : values;
539:   const getY = (value) => padY + (1 - (clamp(value, min, max) - min) / (max - min)) * (height - padY * 2);
540:   const getX = (index) => padX + (index / (graphValues.length - 1)) * (width - padX * 2);
541: 
542:   const points = graphValues.map((value, index) => ({ x: getX(index), y: getY(value) }));
543: 
544:   ctx.beginPath();
545:   ctx.moveTo(points[0].x, height);
546:   ctx.lineTo(points[0].x, points[0].y);
547:   for (let i = 1; i < points.length; i += 1) {
548:     const prev = points[i - 1];
549:     const point = points[i];
550:     const midX = (prev.x + point.x) / 2;
551:     ctx.bezierCurveTo(midX, prev.y, midX, point.y, point.x, point.y);
552:   }
553:   ctx.lineTo(points[points.length - 1].x, height);
554:   ctx.closePath();
555:   const fill = ctx.createLinearGradient(0, 0, 0, height);
556:   fill.addColorStop(0, "rgba(201, 255, 102, 0.2)");
557:   fill.addColorStop(1, "rgba(201, 255, 102, 0)");
558:   ctx.fillStyle = fill;
559:   ctx.fill();
560: 
561:   ctx.beginPath();
562:   ctx.moveTo(points[0].x, points[0].y);
563:   for (let i = 1; i < points.length; i += 1) {
564:     const prev = points[i - 1];
565:     const point = points[i];
566:     const midX = (prev.x + point.x) / 2;
567:     ctx.bezierCurveTo(midX, prev.y, midX, point.y, point.x, point.y);
568:   }
569:   const stroke = ctx.createLinearGradient(0, 0, width, 0);
570:   stroke.addColorStop(0, "#58f0c0");
571:   stroke.addColorStop(1, "#caff72");
572:   ctx.strokeStyle = stroke;
573:   ctx.lineWidth = 3;
574:   ctx.shadowColor = "rgba(140, 255, 164, 0.48)";
575:   ctx.shadowBlur = 10;
576:   ctx.stroke();
577:   ctx.shadowBlur = 0;
578: 
579:   const last = points[points.length - 1];
580:   ctx.beginPath();
581:   ctx.arc(last.x, last.y, 6.5, 0, Math.PI * 2);
582:   ctx.fillStyle = "rgba(202, 255, 114, 0.18)";
583:   ctx.fill();
584:   ctx.beginPath();
585:   ctx.arc(last.x, last.y, 3.2, 0, Math.PI * 2);
586:   ctx.fillStyle = "#d8ff86";
587:   ctx.fill();
588: 
589:   const previous = values.length > 1 ? values[values.length - 2] : values[values.length - 1];
590:   const delta = (values[values.length - 1] || 0) - previous;
591:   els.chartDelta.textContent = `${delta >= 0 ? "+" : "−"}${Math.abs(delta).toFixed(1)}`;
592:   els.chartDelta.style.color = delta >= 0 ? "var(--mint)" : "var(--coral)";
593: }
