607: function pickDominantPressure(org) {
608:   const weights = org.evaluation.weights;
609:   const entries = Object.entries(weights).sort((a, b) => b[1] - a[1]);
610:   const labels = {
611:     thermal: "thermoregulation",
612:     foraging: "forage access",
613:     defense: "predator defense",
614:     efficiency: "metabolic efficiency",
615:   };
616:   return labels[entries[0][0]];
