619: function advanceGeneration({ automatic = false } = {}) {
620:   if (state.transitioning) return;
621:   hideHint();
622:   state.transitioning = true;
623:   const before = meanFitness();
624:   const parents = rankPopulation(state.population);
625:   const seeded = breedPopulation(state.population, state.env, random);
626:   const nextOrganisms = seeded.map((item) => makeOrganism(item.genome, {
627:     origin: item.origin,
628:     changes: item.changes,
629:     parents: item.parents,
630:   }));
631: 
632:   state.population = nextOrganisms;
633:   const previousStage = state.stage;
634:   state.generation += 1;
635:   state.stage = state.generation >= 4 ? "organism" : "cellular";
636:   state.mutagen = Math.min(5, state.mutagen + 2);
637:   state.autoTimer = 0;
638:   creatures.selectedIndex = 0;
639:   creatures.spawnPopulation(state.population, SPAWN_POSITIONS, state.stage);
640:   creatures.select(0, true);
641: 
642:   recordHistory();
643:   const mean = meanFitness();
644:   const top = rankPopulation(state.population)[0];
645:   const pressure = pickDominantPressure(top);
646:   const changes = nextOrganisms.flatMap((org) => org.changes || []);
647:   const strongest = changes.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))[0];
648: 
649:   els.btnAuto.classList.toggle("paused", !state.auto);
650: 
651:   addLog(
652:     `Generation ${pad(state.generation)} ${state.stage === "organism" && previousStage === "cellular" ? "developed into multicellular organisms" : "hatched"}. Mean fitness <b>${mean.toFixed(1)}</b>; ${pressure} led selection.`,
653:     true,
654:   );
655:   if (strongest) {
656:     const desc = describeChange(strongest);
657:     addLog(`Dominant mutation: ${desc.detail.toLowerCase()} — ${desc.title}.`);
658:   } else {
659:     addLog(`The leading genome was preserved intact. ${parents.length ? "Stability can be a strategy." : ""}`);
660:   }
661: 
662:   const selectedCreature = creatures.selected;
663:   if (selectedCreature) {
664:     world.burst(selectedCreature.position, selectedCreature.accentColor ?? 0xcaff72, 1.15);
665:   }
666: 
667:   const gain = mean - before;
668:   showToast(
669:     previousStage !== state.stage ? "Organism stage reached" : `Generation ${pad(state.generation)} hatched`,
670:     previousStage !== state.stage
671:       ? `Cell lineages now develop into multicellular organisms · ${gain >= 0 ? "+" : "−"}${Math.abs(gain).toFixed(1)} fitness`
672:       : `${gain >= 0 ? "+" : "−"}${Math.abs(gain).toFixed(1)} fitness · ${state.population.filter((o) => o.changes.length).length} new alleles`,
673:     strongest ? "◈" : "✦",
674:     3600,
675:   );
676:   if (automatic) addLog("Automatic selection advanced the lineage.");
677:   updateAll();
678:   audio.evolve();
679: 
680:   if (!state.milestoneShown && state.generation >= 5 && mean >= 72) {
681:     state.milestoneShown = true;
682:     setTimeout(() => {
683:       showToast("Stable lineage established", `${mean.toFixed(1)} mean fitness · the basin is adapting around your creatures`, "❖", 5200);
684:       addLog("Milestone: a stable lineage now occupies the basin.", true);
685:     }, 900);
686:   }
687: 
688:   setTimeout(() => {
689:     state.transitioning = false;
690:   }, 360);
691: }
