708: function directMutation(gene = null) {
709:   if (state.transitioning) return;
710:   hideHint();
711:   const org = currentOrganism();
712:   const creature = creatures.selected;
713:   if (!org || !creature) return;
714:   if (state.mutagen <= 0) {
715:     showToast("Mutagen reserve depleted", "Advance a generation to replenish the reserve", "!", 3000);
716:     audio.error();
717:     return;
718:   }
719: 
720:   const key = gene || TRAIT_ROWS[Math.floor(random() * TRAIT_ROWS.length)];
721:   const result = mutateGene(org.genome, key, random, 0.17);
722:   org.genome = result.genome;
723:   org.evaluation = evaluate(org.genome, state.env, org.condition);
724:   org.changes = result.changes;
725:   state.mutagen -= 1;
726:   creatures.replace(creatures.selectedIndex, org);
727:   const mutated = creatures.selected;
728:   world.burst(mutated.position, mutated.accentColor ?? 0xcaff72, 0.75);
729: 
730:   const change = result.changes[0];
731:   const info = describeChange(change);
732:   showToast(info.title, `${info.detail} · directed mutation expressed`, "⌁", 3300);
733:   addLog(`Directed mutation: <b>${info.title}</b> in specimen K-${pad(creatures.selectedIndex + 1)}.`, true);
734:   if (state.history.length) state.history[state.history.length - 1] = meanFitness();
735:   updateAll();
736:   audio.mutate();
737: }
