import { spawn } from 'node:child_process';
import { writeFile } from 'node:fs/promises';

const browser = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
  '--remote-debugging-port=9223', '--user-data-dir=/tmp/opencode/helix-smoke-profile',
  'http://127.0.0.1:5173/'
], { stdio: 'ignore' });
let socket;
try {
  let targets;
  for (let attempt = 0; attempt < 30; attempt++) {
    try {
      targets = await (await fetch('http://127.0.0.1:9223/json')).json();
      if (targets.some((target) => target.type === 'page')) break;
    } catch {}
    await new Promise((resolve) => setTimeout(resolve, 300));
  }
  const page = targets?.find((target) => target.type === 'page');
  if (!page) throw new Error('Chromium page target did not start');
  socket = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    socket.addEventListener('open', resolve, { once: true });
    socket.addEventListener('error', reject, { once: true });
  });
  let nextId = 0;
  const pending = new Map();
  socket.addEventListener('message', (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      message.error ? reject(new Error(message.error.message)) : resolve(message.result);
    }
  });
  const call = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    socket.send(JSON.stringify({ id, method, params }));
  });
  await call('Page.enable');
  await call('Runtime.enable');
  let state;
  for (let attempt = 0; attempt < 30; attempt++) {
    const result = await call('Runtime.evaluate', {
      expression: `({ready:document.readyState,generation:document.querySelector('#stat-generation')?.textContent,energyLabel:document.querySelector('#fit-energy')?.previousElementSibling?.textContent})`,
      returnByValue: true
    });
    state = result.result.value;
    if (state.ready === 'complete' && state.generation) break;
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  const clickResult = await call('Runtime.evaluate', {
    expression: `document.querySelector('#btn-evolve').click(); new Promise(resolve => setTimeout(() => resolve(document.querySelector('#stat-generation').textContent), 1400))`,
    awaitPromise: true,
    returnByValue: true
  });
  const afterGeneration = clickResult.result.value;
  const shot = await call('Page.captureScreenshot', { format: 'jpeg', quality: 85, captureBeyondViewport: false });
  await writeFile('/tmp/opencode/helix-latest.jpg', Buffer.from(shot.data, 'base64'));
  console.log(JSON.stringify({ initialGeneration: state.generation, energyLabel: state.energyLabel, afterAdvance: afterGeneration, screenshot: '/tmp/opencode/helix-latest.jpg' }));
} finally {
  socket?.close();
  browser.kill('SIGTERM');
}

